// KAT runner for the JS port. Lives outside /output on purpose: the deliverable
// itself must not use child_process, but this harness may.
//   node /tmp/run_kat.mjs [pathToEntry]      (default /output/test6.mjs)
import { spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';

const entry = process.argv[2] ?? '/output/test6.mjs';
const corpus = JSON.parse(readFileSync('/tmp/kat_corpus.json', 'utf8'));

let pass = 0;
const failures = [];
for (const [i, c] of corpus.entries()) {
  const r = spawnSync(process.execPath,
    [entry, '--a', c.passphrase, '--b', c.salt, '--c', c.passphrase, '--d', c.salt],
    { encoding: 'utf8', maxBuffer: 1 << 24 });
  const want = `${c.expected}\n${c.expected}\n`;
  if (r.status === 0 && r.stdout === want && r.stderr === '') pass++;
  else failures.push({ i, exit: r.status, got: r.stdout, want, stderr: r.stderr,
                       passphrase: c.passphrase, salt: c.salt });
}
for (const f of failures.slice(0, 20)) {
  console.log(`FAIL #${f.i} exit=${f.exit}\n  passphrase=${JSON.stringify(f.passphrase)}\n  salt=${JSON.stringify(f.salt)}\n  got =${JSON.stringify(f.got)}\n  want=${JSON.stringify(f.want)}\n  stderr=${JSON.stringify(f.stderr)}`);
}
console.log(`${pass}/${corpus.length} passed, ${failures.length} failed`);
process.exit(failures.length ? 1 : 0);
